# 批量结算：先求金额总和，再按折扣率四舍五入到分。


def total_cents(prices, rate_bp):
    return sum((p * rate_bp + 50) // 100 for p in prices)

verification_tests:
from target import total_cents


def test_single_price():
    assert total_cents([100], 50) == 50


def test_empty_prices():
    assert total_cents([], 50) == 0


def test_rounding_applies_to_total_only():
    assert total_cents([1, 1, 1], 50) == 2
